/** Picks a Article from the posts resource */
function ArticleIdPicker({
  id,
  value,
  onChange,
  allowEmpty
}: {
  id: string;
  value: string;
  onChange: (value: string) => void;
  allowEmpty: boolean;
}) {
  const options = useQuery({ queryKey: ["posts", "list", { page_size: 200 }], queryFn: () => client.posts.list({ page_size: 200 }) });
  return (
    <select id={id} className={selectClass} value={value} onChange={e => onChange(e.target.value)}>
      {allowEmpty ? <option value="">—</option> : null}
      {(options.data?.data ?? []).map(item => (
        <option key={text(item.id)} value={text(item.id)}>
          {text(item.title)}
        </option>
      ))}
    </select>
  );
}

type ModerationSetter = <K extends keyof ModerationValues>(key: K, value: ModerationValues[K]) => void;

function renderModerationField(field: ModerationField, values: ModerationValues, set: ModerationSetter) {
  switch (field) {
    case "body":
      return (
      <FormRow label="Body" htmlFor="body">
        <Textarea id="body" rows={4} value={values.body} onChange={e => set("body", e.target.value)} required />
      </FormRow>
      );
    case "article_id":
      return (
      <FormRow label="Article" htmlFor="article_id">
        <ArticleIdPicker id="article_id" value={values.article_id} onChange={value => set("article_id", value)} allowEmpty={false} />
      </FormRow>
      );
  }
}

function ModerationForm({
  fields,
  initial,
  submitLabel,
  pending,
  error,
  onSubmit,
  onCancel
}: {
  fields: readonly ModerationField[];
  initial: ModerationValues;
  submitLabel: string;
  pending: boolean;
  error: { message: string } | null;
  onSubmit: (values: ModerationValues) => void;
  onCancel?: () => void;
}) {
  const [values, setValues] = useState<ModerationValues>(initial);
  const [problem, setProblem] = useState<string | null>(null);
  const set: ModerationSetter = (key, value) => setValues(current => ({ ...current, [key]: value }));
  const submit = (event: FormEvent) => {
    event.preventDefault();
    setProblem(null);
    try {
      onSubmit(values);
    } catch (err) {
      setProblem(err instanceof Error ? err.message : String(err));
    }
  };
  return (
    <form onSubmit={submit} className="grid max-w-xl gap-4">
      {fields.map(field => (
        <Fragment key={field}>{renderModerationField(field, values, set)}</Fragment>
      ))}
      <ErrorNote error={error ?? (problem ? { message: problem } : null)} />
      <div className="flex gap-2">
        <Button type="submit" disabled={pending}>
          {submitLabel}
        </Button>
        {onCancel ? (
          <Button type="button" variant="ghost" onClick={onCancel}>
            Cancel
          </Button>
        ) : null}
      </div>
    </form>
  );
}

